class Solution {
public:
    string firstPalindrome(vector<string>& words) {
        for (const string& w : words) {
            int i = 0, j = (int)w.size() - 1;
            bool ok = true;
            while (i < j) {
                if (w[i] != w[j]) {
                    ok = false;
                    break;
                }
                ++i;
                --j;
            }
            if (ok) return w;
        }
        return "";
    }
};
